"""Self-contained HTML for the waiting jumper mini game."""


def game_html():
    """Return one inline-only canvas game document."""
    return r'''<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#fff}
body{font-family:Arial,sans-serif;color:#252338}.wrap{width:100%;height:auto;min-height:260px;padding:10px 14px 8px;border:1px solid #eeeaf3;border-radius:16px;background:linear-gradient(135deg,#fff8fc,#faf7ff)}
.top{display:flex;justify-content:space-between;align-items:center;margin:0 auto 6px;width:min(100%,720px);font-size:13px;font-weight:700}.score{color:#a83cf0}.hint{width:min(100%,720px);margin:5px auto 0;font-size:11px;color:#858493;font-weight:400}
.stage{width:100%;display:flex;justify-content:center}canvas{display:block;width:100%;max-width:720px;height:auto;aspect-ratio:900/240;border-radius:11px;background:linear-gradient(#fff 0%,#fff8fc 72%,#f7edfb 100%);touch-action:manipulation;image-rendering:crisp-edges}
</style></head><body><main class="wrap"><div class="top"><span>Play while you wait</span><span class="score">Ignored: <b id="ignored">0</b> | Best: <b id="best">0</b></span></div><div class="stage"><canvas id="game" width="900" height="240" tabindex="0" aria-label="Help the runner ignore distractions"></canvas></div><div class="hint" id="hint">Space, Arrow Up, or tap to jump</div></main>
<script>
(()=>{
const LOGICAL_WIDTH=900,LOGICAL_HEIGHT=240;
const SVG_NS='ht'+'tp://www.w3.org/2000/svg';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),ignoredEl=document.getElementById('ignored'),bestEl=document.getElementById('best'),hint=document.getElementById('hint');
const START_SPEED=330,SPEED_CAP=1.4,OBSTACLE_WIDTH=30,PLAYER_WIDTH=40,PLAYER_HEIGHT=60,JUMP_AIRTIME=.55,GRAVITY=2400,JUMP_VELOCITY=GRAVITY*JUMP_AIRTIME/2;
const LABELS=['Ad','Spam','Promo','T&C','Intro','Sub','Bio','Poll'];
const RUN_POSES=[
{backLeg:'M43 62 L34 76 L23 86',frontLeg:'M49 62 L58 75 L70 82',backArm:'M45 37 L34 47 L28 57',frontArm:'M57 37 L69 43 L75 34'},
{backLeg:'M44 62 L39 77 L28 87',frontLeg:'M50 62 L62 70 L72 82',backArm:'M46 37 L37 42 L31 31',frontArm:'M58 37 L69 49 L75 58'},
{backLeg:'M45 62 L34 72 L23 79',frontLeg:'M51 62 L57 78 L71 87',backArm:'M46 37 L36 50 L30 58',frontArm:'M59 37 L70 31 L77 39'},
{backLeg:'M44 62 L40 75 L27 82',frontLeg:'M51 62 L63 76 L73 86',backArm:'M46 37 L37 31 L31 39',frontArm:'M59 37 L70 47 L77 42'}
];
let dpr=1,ground=197,player,blocks=[],lastSpawned=null,pendingObstacle=null,pendingGap=0,pendingGapFactor=1,ignored=0,best=0,speed=START_SPEED,elapsed=0,worldDistance=0,over=false,started=false,lastTime=0,speedFlashUntil=0,speedBumpShown=false,landingPuff=0,runnerFrames=[];
try{best=Number(localStorage.getItem('reel-jump-best')||0)||0}catch(e){}bestEl.textContent=best;

function nextGap(speed,jumpAirtime,obstacleWidth,playerWidth,factor){const jumpDistance=speed*jumpAirtime,minGap=Math.max(jumpDistance*.9,obstacleWidth+playerWidth)+speed*.35;return minGap*(factor===undefined?1+Math.random()*1.2:factor)}
function speedForScore(points){if(points<200)return START_SPEED;return START_SPEED*Math.min(SPEED_CAP,1.1+Math.floor((points-200)/50)*.005)}
function makeObstacle(){return{x:LOGICAL_WIDTH,w:OBSTACLE_WIDTH,h:26+Math.random()*14,label:LABELS[Math.floor(Math.random()*LABELS.length)]}}
function prepareNextObstacle(){pendingObstacle=makeObstacle();pendingGapFactor=1+Math.random()*1.2;pendingGap=nextGap(speed,JUMP_AIRTIME,OBSTACLE_WIDTH,PLAYER_WIDTH,pendingGapFactor)}
function runnerSvg(pose,hit=false,jumpPose=false){
const leftLeg=jumpPose?'M43 62 L36 72 L45 79':pose.backLeg,rightLeg=jumpPose?'M50 62 L61 69 L68 78':pose.frontLeg;
const leftArm=jumpPose?'M45 37 L34 28 L29 12':pose.backArm,rightArm=jumpPose?'M58 37 L68 46 L76 43':pose.frontArm;
return `<svg xmlns="${SVG_NS}" width="90" height="100" viewBox="0 0 90 100"><defs><linearGradient id="j" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ff77bd"/><stop offset=".55" stop-color="#e6007e"/><stop offset="1" stop-color="#923de0"/></linearGradient></defs><g stroke="#30243d" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="${leftLeg}" fill="none" stroke="#29263a" stroke-width="7"/><path d="M23 86 q-5 0-7 4 l12 2 q4 0 5-3" fill="#fff"/><path d="M18 91 l14 2" stroke="#e6007e" stroke-width="3"/><path d="${rightLeg}" fill="none" stroke="#29263a" stroke-width="7"/><path d="M69 82 q7 0 11 5 l-13 2 q-4 0-5-3" fill="#fff"/><path d="M64 87 l14 2" stroke="#e6007e" stroke-width="3"/><path d="${leftArm}" fill="none" stroke="url(#j)" stroke-width="9"/><path d="${rightArm}" fill="none" stroke="url(#j)" stroke-width="9"/><path d="M46 29 Q59 26 69 34 L67 61 Q56 68 41 61 L38 37 Z" fill="url(#j)"/><path d="M42 34 Q31 39 34 49" fill="none" stroke="#30243d" stroke-width="1.5"/><path d="M52 30 Q54 37 61 38" fill="none" stroke="#f7c7eb" stroke-width="1.4"/><path d="M50 39 L60 41" fill="none" stroke="#f7c7eb" stroke-width="1.4"/><path d="M49 58 Q57 62 65 58" fill="none" stroke="#61245f" stroke-width="1.3"/><path d="M49 58 L48 63 M64 58 L64 63" fill="none" stroke="#30243d" stroke-width="1.5"/><path d="M61 7 Q73 8 76 18 L71 28 Q62 29 53 23 L54 13 Z" fill="#d9916c"/><path d="M52 13 Q60 5 75 9 L78 15 Q66 12 56 19 Z" fill="#312640"/><path d="M54 16 L45 13" fill="none" stroke="#312640" stroke-width="4"/><path d="M62 14 Q70 12 74 16 L72 20 Q67 18 62 19 Z" fill="#171625"/><path d="M62 15 L72 15" fill="none" stroke="#a6dcff" stroke-width="1"/><path d="M76 19 l3 1" fill="none" stroke="#30243d" stroke-width="1.5"/><circle cx="55" cy="18" r="3" fill="#d9a5ff" stroke="#30243d" stroke-width="1.2"/><circle cx="55" cy="18" r="1.2" fill="#fff" stroke="none"/>${hit?'<ellipse cx="73" cy="24" rx="2" ry="3.2" fill="#812a74"/><path d="M67 21 Q70 19 72 21 M75 20 Q78 19 80 21" fill="none"/>':'<path d="M70 24 q2 1 4 0" fill="none" stroke="#6e245f" stroke-width="1.2"/>'}</g></svg>`}
function loadFrame(svg){const image=new Image();image.onload=draw;image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);return image}
function buildRunnerFrames(){runnerFrames=RUN_POSES.map(pose=>loadFrame(runnerSvg(pose)));runnerFrames.push(loadFrame(runnerSvg(RUN_POSES[1],false,true)));runnerFrames.push(loadFrame(runnerSvg(RUN_POSES[0],true,false)))}
function reset(){ground=197;player={x:112,y:ground-PLAYER_HEIGHT,vy:0};blocks=[];lastSpawned=null;pendingObstacle=null;pendingGap=0;ignored=0;speed=START_SPEED;elapsed=0;worldDistance=0;over=false;started=false;lastTime=0;speedFlashUntil=0;speedBumpShown=false;landingPuff=0;ignoredEl.textContent='0';hint.textContent='Space, Arrow Up, or tap to jump';draw()}
function resize(){dpr=Math.min(window.devicePixelRatio||1,3);canvas.width=Math.round(LOGICAL_WIDTH*dpr);canvas.height=Math.round(LOGICAL_HEIGHT*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function jump(){canvas.focus({preventScroll:true});if(over){reset();started=true;hint.textContent='';prepareNextObstacle();return}started=true;hint.textContent='';if(player.y>=ground-PLAYER_HEIGHT-.5)player.vy=-JUMP_VELOCITY}
function onKey(event){if(event.code==='Space'||event.code==='ArrowUp'){event.preventDefault();jump()}}
window.addEventListener('keydown',onKey);canvas.addEventListener('pointerdown',jump);window.addEventListener('resize',resize);

function maybeSpawn(){if(!pendingObstacle)prepareNextObstacle();if(!lastSpawned){if(worldDistance<330)return;pendingObstacle.x=LOGICAL_WIDTH;blocks.push(pendingObstacle);lastSpawned=pendingObstacle;prepareNextObstacle();return}pendingGap=nextGap(speed,JUMP_AIRTIME,OBSTACLE_WIDTH,PLAYER_WIDTH,pendingGapFactor);const nextX=lastSpawned.x+lastSpawned.w+pendingGap;if(nextX<=LOGICAL_WIDTH){pendingObstacle.x=nextX;blocks.push(pendingObstacle);lastSpawned=pendingObstacle;prepareNextObstacle()}}
function drawBackground(){ctx.clearRect(0,0,LOGICAL_WIDTH,LOGICAL_HEIGHT);const drift=worldDistance*.07;for(let i=0;i<6;i++){const cx=((i*181-drift)%(LOGICAL_WIDTH+100)+LOGICAL_WIDTH+100)%(LOGICAL_WIDTH+100)-45,cy=27+(i%3)*21;ctx.fillStyle=i%2?'rgba(230,0,126,.055)':'rgba(168,60,240,.07)';ctx.beginPath();ctx.arc(cx,cy,13,0,Math.PI*2);ctx.arc(cx+14,cy+2,10,0,Math.PI*2);ctx.arc(cx-13,cy+4,9,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#eadff2';ctx.fillRect(0,ground,LOGICAL_WIDTH,2);ctx.fillStyle='rgba(143,56,209,.25)';for(let x=0;x<LOGICAL_WIDTH+16;x+=24){const dx=(x-worldDistance*.48%(LOGICAL_WIDTH+24)+LOGICAL_WIDTH+24)%(LOGICAL_WIDTH+24);ctx.beginPath();ctx.arc(dx,ground+11,1.5,0,Math.PI*2);ctx.fill()}}
function drawSpeedLines(){if(!started||over||player.y<ground-PLAYER_HEIGHT-.5)return;const lines=2+(Math.floor(elapsed*5)%2);ctx.strokeStyle='rgba(230,0,126,.32)';ctx.lineWidth=2;for(let i=0;i<lines;i++){const y=player.y+18+i*12,x=player.x-26-(i%2)*8;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-11,y);ctx.stroke()}}
function drawDust(){if(landingPuff<=0)return;ctx.globalAlpha=Math.min(.55,landingPuff*1.8);ctx.fillStyle='#cf9be7';ctx.beginPath();ctx.ellipse(player.x-4,ground-3,10+(1.2-landingPuff)*12,3+(1.2-landingPuff)*3,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function drawNameTag(){const headX=player.x+9,y=player.y-3-12;ctx.font='700 7px Arial';ctx.textAlign='center';ctx.textBaseline='middle';const w=35,h=12,x=headX-w/2;const gradient=ctx.createLinearGradient(x,y,x+w,y+h);gradient.addColorStop(0,'#e6007e');gradient.addColorStop(1,'#a83cf0');ctx.fillStyle=gradient;ctx.beginPath();ctx.roundRect(x,y,w,h,6);ctx.fill();ctx.fillStyle='#fff';ctx.fillText('GEN Z',headX,y+h/2+.2)}
function drawRunner(){drawDust();drawSpeedLines();const airborne=player.y<ground-PLAYER_HEIGHT-.5;let index;if(over)index=5;else if(airborne)index=4;else index=Math.floor(elapsed*(5+speed/35))%4;const frame=runnerFrames[index];if(frame&&frame.complete&&frame.naturalWidth)ctx.drawImage(frame,player.x-27,player.y,54,60);drawNameTag()}
function drawObstacle(block){const y=ground-block.h;ctx.fillStyle='rgba(82,35,92,.10)';ctx.beginPath();ctx.ellipse(block.x+OBSTACLE_WIDTH/2,ground+2,OBSTACLE_WIDTH*.42,3,0,0,Math.PI*2);ctx.fill();const fill=ctx.createLinearGradient(block.x,y,block.x+OBSTACLE_WIDTH,y+block.h);fill.addColorStop(0,'#b252e2');fill.addColorStop(1,'#8235b9');ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(block.x,y,OBSTACLE_WIDTH,block.h,5);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#fff';ctx.font='5px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(block.label,block.x+OBSTACLE_WIDTH/2,y+block.h/2)}
function draw(){if(!player)return;drawBackground();for(const block of blocks)drawObstacle(block);drawRunner();if(performance.now()<speedFlashUntil){ctx.fillStyle='#a83cf0';ctx.font='bold 13px Arial';ctx.textAlign='center';ctx.fillText('speed up',650,25)}if(over){ctx.fillStyle='rgba(255,255,255,.60)';ctx.fillRect(0,0,LOGICAL_WIDTH,LOGICAL_HEIGHT);ctx.fillStyle='#30253d';ctx.textAlign='center';ctx.font='bold 18px Arial';ctx.fillText('Caught by an ad. Space or tap to restart',LOGICAL_WIDTH/2,LOGICAL_HEIGHT/2+5)}}
function update(dt){if(!started||over)return;elapsed+=dt;worldDistance+=speed*dt;ignored=worldDistance/42;const wholeIgnored=Math.floor(ignored);ignoredEl.textContent=wholeIgnored;const nextSpeed=speedForScore(wholeIgnored);if(!speedBumpShown&&wholeIgnored>=200){speedBumpShown=true;speedFlashUntil=performance.now()+950}speed=nextSpeed;maybeSpawn();for(const block of blocks)block.x-=speed*dt;blocks=blocks.filter(block=>block.x+block.w>0);if(lastSpawned&&!blocks.includes(lastSpawned))lastSpawned=blocks[blocks.length-1]||null;const wasAirborne=player.y<ground-PLAYER_HEIGHT-.5;player.vy+=GRAVITY*dt;player.y+=player.vy*dt;if(player.y>ground-PLAYER_HEIGHT){if(wasAirborne)landingPuff=1;player.y=ground-PLAYER_HEIGHT;player.vy=0}landingPuff=Math.max(0,landingPuff-dt*2.5);const pLeft=player.x-PLAYER_WIDTH/2+4,pRight=player.x+PLAYER_WIDTH/2-4,pTop=player.y+3,pBottom=player.y+PLAYER_HEIGHT-3;for(const block of blocks){const bTop=ground-block.h;if(pRight>block.x&&pLeft<block.x+OBSTACLE_WIDTH&&pBottom>bTop&&pTop<ground){over=true;hint.textContent='';const result=Math.floor(ignored);if(result>best){best=result;bestEl.textContent=best;try{localStorage.setItem('reel-jump-best',String(best))}catch(e){}}break}}}
function tick(time){requestAnimationFrame(tick);if(!lastTime)lastTime=time;const dt=Math.min(.04,(time-lastTime)/1000);lastTime=time;update(dt);draw()}
function init(){buildRunnerFrames();resize();reset();requestAnimationFrame(tick)}init()
})();
</script></body></html>'''
